#!/usr/bin/env python3
"""
Complete Verified Question Registry for Chapter 5: Optical Mineralogy (Q61 to Q125)
Dr. Ausaf Sayeed - Objective Geology (125 Total Questions)
"""

REMAINING_QS_CH5 = {
    61: ("Anomalous Interference Colors: Dispersive Retardation in Chlorite and Zoisite", "Interference colors that deviate markedly from the normal progression of the Michel-Lévy chart (such as the diagnostic 'Berlin blue', 'peacock blue', or anomalous brown) are termed anomalous interference colors and are characteristically exhibited by :", {"A": "Chlorite (penninite/clinochlore), Zoisite, and Vesuvianite", "B": "Quartz", "C": "Calcite", "D": "Halite"}, "Nesse (Introduction to Optical Mineralogy, p. 55); Deer, Howie & Zussman"),
    62: ("Uniaxial Interference Figure: Melatope, Isogyres, and Isochromes", "In a centered optic axis interference figure of a uniaxial mineral observed under conoscopic illumination, the black cross consists of :", {"A": "Isochromes", "B": "Circular sections", "C": "Vibration directions only", "D": "Isogyres (black cross whose intersection point, the Melatope, marks the emergence of the optic axis)"}, "Bloss (Optical Crystallography, Ch. 6, pp. 80–92); Nesse (pp. 70–75)"),
    63: ("Biaxial Optic Axis Figure: Isogyre Curvature and 2V", "In a centered optic axis interference figure of a biaxial mineral, as the stage is rotated into the 45° position, the single isogyre curves into a hyperbola whose degree of curvature is :", {"A": "Independent of 2V", "B": "Directly proportional to 2V (a perfectly straight isogyre indicates 2V = 90°; higher curvature indicates smaller 2V)", "C": "Zero", "D": "Always 180°"}, "Nesse (Introduction to Optical Mineralogy, pp. 90–94); Bloss"),
    64: ("Flash Figures: Uniaxial Sections Parallel to the Optic Axis", "A 'flash figure' is an interference figure that forms a broad, fuzzy black cross occupying the entire field of view which rapidly breaks and sweeps out of the field upon minor stage rotation (<5°), obtained on sections cut :", {"A": "Perpendicular to the optic axis", "B": "At 45° to the optic axis", "C": "Perpendicular to a cleavage crack", "D": "Parallel to the optic axis (principal section of maximum birefringence)"}, "Wahlstrom (Optical Crystallography, p. 82); Nesse (p. 74)"),
    65: ("Uniaxial Optic Sign Testing: Gypsum Plate in Northeast Quadrant", "When a first-order red (gypsum) plate (550 nm) is inserted into a centered uniaxial optic axis figure, if the color in the Northwest and Southeast quadrants shifts to Yellow (subtraction) while the Northeast and Southwest quadrants shift to Blue (addition), the mineral is :", {"A": "Uniaxial negative", "B": "Uniaxial positive (addition in NE/SW quadrants)", "C": "Biaxial positive", "D": "Isotropic"}, "Nesse (Introduction to Optical Mineralogy, pp. 78–82); Bloss (p. 86)"),
    66: ("Mallard's Equation: Quantitative Measurement of 2V", "In an acute bisectrix (Bxa) interference figure, the true optic axial angle 2V is quantitatively related to the linear separation 2D between the melatopes on the ocular micrometer scale by Mallard's equation :", {"A": "D = K * tan V", "B": "D = K * cos V", "C": "D = K * n_beta", "D": "D = K * sin E = K * n_beta * sin V (where K is Mallard's microscope constant)"}, "Ernest Mallard (1882); Bloss (Optical Crystallography, pp. 140–145); Nesse"),
    67: ("Interference Figure Classification: Symmetry and Orientation", "Match the orientation of the mineral thin section with its diagnostic conoscopic interference figure :\n(A) Section perpendicular to optic axis in quartz — (1) Centered uniaxial optic axis figure\n(B) Section perpendicular to acute bisectrix in muscovite — (2) Centered acute bisectrix (Bxa) figure\n(C) Section parallel to optic axis in calcite — (3) Flash figure\n(D) Section perpendicular to one optic axis in augite — (4) Biaxial optic axis figure", {"A": "A-2, B-1, C-4, D-3", "B": "A-1, B-3, C-2, D-4", "C": "A-1, B-2, C-3, D-4", "D": "A-4, B-3, C-1, D-2"}, "Nesse (Introduction to Optical Mineralogy, Ch. 6); Bloss"),
    68: ("Stage Rotation Colors: Variation in Interference Intensity", "As an anisotropic mineral grain is rotated on the microscope stage between crossed polarizers, the hue (color) of the interference tint remains constant while the :", {"A": "Refractive index changes", "B": "Intensity (brightness) of the interference color varies from zero at extinction to maximum at the 45° position (I = I_0 * sin^2(2*theta))", "C": "Thickness changes", "D": "Pleochroic scheme inverts"}, "Wahlstrom (Optical Crystallography, p. 88); Nesse (p. 39)"),
    69: ("Birefringence and Interference Color Intensity", "For two mineral grains of identical standard thickness (0.03 mm), the mineral possessing the higher numerical birefringence (delta) will produce :", {"A": "A lower optical retardation", "B": "A lower order of interference color", "C": "A higher optical retardation (Delta = d * delta) and consequently higher-order interference colors on the Michel-Lévy chart", "D": "Total darkness"}, "Nesse (Introduction to Optical Mineralogy, p. 52); Bloss"),
    70: ("Retardation Formula: Mathematical Definition", "Optical retardation (Delta) between the slow wave and the fast wave in an anisotropic crystal is quantitatively defined as :", {"A": "Delta = d / (N - n)", "B": "Delta = (N + n) / d", "C": "Delta = d * (N - n) = d * delta (where d is thickness, N is slow index, n is fast index)", "D": "Delta = d * (N^2 - n^2)"}, "Nesse (Introduction to Optical Mineralogy, p. 50); Jenkins & White"),
    71: ("Quartz Birefringence: Numerical Value", "The numerical birefringence of Quartz (SiO2) for the sodium D-line (589.3 nm) is :", {"A": "0.009 (n_epsilon = 1.553, n_omega = 1.544)", "B": "0.040", "C": "0.172", "D": "0.002"}, "Deer, Howie & Zussman (Introduction to the Rock-Forming Minerals); Nesse"),
    72: ("Calcite Birefringence: Extreme Numerical Value", "The numerical birefringence of Calcite (CaCO3) for the sodium D-line is :", {"A": "0.009", "B": "0.025", "C": "0.050", "D": "0.172 (n_omega = 1.658, n_epsilon = 1.486, delta = -0.172)"}, "Deer, Howie & Zussman (Rock-Forming Minerals); Klein & Dutrow"),
    73: ("Accessory Plates: Quarter-Wave Plate Retardation", "Which optical accessory plate is explicitly constructed to produce a fixed optical retardation of one-quarter wavelength (lambda/4 approx 147 nm) ?", {"A": "Gypsum / Selenite plate (550 nm)", "B": "Mica plate (147 nm)", "C": "Quartz wedge (variable 0-2500 nm)", "D": "Berek compensator"}, "Nesse (Introduction to Optical Mineralogy, p. 77); Bloss"),
    74: ("Precise Extinction Measurement: The Nakamura Half-Shadow Plate", "The most sensitive and precise petrographic accessory device utilized to determine the exact extinction angle of a weakly birefringent mineral is the :", {"A": "Bertrand lens", "B": "Iris diaphragm", "C": "Quartz wedge", "D": "Nakamura half-shadow plate (or Wright biquartz ocular plate)"}, "Wahlstrom (Optical Crystallography, p. 55); Bloss (p. 78)"),
    75: ("Optical Compensator: The Berek Compensator Principle", "The Berek compensator is an optical instrument utilized for highly accurate quantitative retardation measurements, consisting of a :", {"A": "Graduated quartz wedge", "B": "Fixed mica sheet", "C": "Polished plate of optical calcite cut perpendicular to the optic axis that can be tilted precisely on a calibrated horizontal rotation axis", "D": "Fluorite prism"}, "Max Berek (1913); Bloss (Optical Crystallography, pp. 92–95); Nesse"),
    76: ("Berek Compensator Calcite Plate: Optical Orientation", "In the construction of the Berek compensator, the calcite plate is polished precisely :", {"A": "Perpendicular to the optic axis (parallel to the basal pinacoid {0001}), ensuring zero initial retardation at normal incidence", "B": "Parallel to the optic axis", "C": "At 45° to the optic axis", "D": "Along the rhombohedral cleavage"}, "Bloss (Optical Crystallography, p. 93); Wahlstrom"),
    77: ("Selenite Plate: Mineralogy and Cleavage", "The 'Selenite Plate' accessory plate is fabricated from a cleavage flake of gypsum (CaSO4.2H2O) cleaved cleanly parallel to its perfect :", {"A": "Basal pinacoid {001}", "B": "Orthopinacoid {100}", "C": "Clinopinacoid {010} (yielding a plate of uniform thickness with known optical orientation)", "D": "Prism face {110}"}, "Bloss (Optical Crystallography, p. 84); Nesse (p. 76)"),
    78: ("Thin Section Thickness: Measurement Standard", "The standard thickness of rock thin sections manufactured for research and petrographic examinations is universally fixed at :", {"A": "0.03 mm (30 micrometers = 0.003 cm)", "B": "0.30 mm", "C": "0.003 mm", "D": "0.15 mm"}, "Nesse (Introduction to Optical Mineralogy, p. 52); Kerr"),
    79: ("Reflected Light Microscopy: Opaque Mineral Identification", "Opaque ore minerals (such as Galena, Chalcopyrite, Magnetite, and Pyrite) that do not transmit light in 0.03 mm thin sections are examined under the ore microscope using :", {"A": "Reflected (incident) plane-polarized light (ore petrography / metallography)", "B": "Conoscopic transmitted light", "C": "Ultraviolet darkfield", "D": "X-ray transmission"}, "Craig & Vaughan (Ore Microscopy and Ore Petrography); Nesse"),
    80: ("Isogyre Rotation Behavior: Uniaxial Cross Invariance", "In a centered uniaxial optic axis interference figure, as the microscope stage is rotated through a full 360° :", {"A": "The black cross splits into two hyperbolas", "B": "The black cross remains stationary and unbroken, parallel to the ocular crosshairs, because vibration directions remain aligned with the polarizers", "C": "The figure disappears completely", "D": "The cross rotates at twice the speed of the stage"}, "Bloss (Optical Crystallography, p. 82); Nesse (p. 72)"),
    81: ("Off-Centered Uniaxial Figures: Eccentric Melatope Migration", "When a uniaxial crystal is cut slightly oblique to the optic axis, the melatope lies outside the center of the field of view, and upon stage rotation :", {"A": "The cross splits into two wide hyperbolas", "B": "The melatope remains fixed in the center", "C": "The center of the cross (melatope) orbits around the center of the field of view in a circular path, while the arms of the cross maintain their parallel orientation to the crosshairs", "D": "The figure inverts its optic sign"}, "Nesse (Introduction to Optical Mineralogy, p. 73); Bloss"),
    82: ("Orthorhombic Extinction: Parallel Extinction Diagnostic", "In the Orthorhombic crystal system, prismatic crystals and sections cut parallel to {100}, {010}, or {001} pinacoids characteristically display :", {"A": "Straight (parallel) or symmetrical extinction, because the optical indicatrix axes X, Y, Z coincide with the crystallographic axes a, b, c", "B": "Inclined extinction at 45°", "C": "Total isotropic extinction", "D": "Undulose extinction"}, "Nesse (Introduction to Optical Mineralogy, p. 65); Bloss (p. 128)"),
    83: ("Monoclinic Extinction: Orientation Constraints", "In monoclinic minerals (such as clinopyroxenes and amphiboles), straight (parallel) extinction is obtained only on sections cut :", {"A": "Parallel to the (010) plane", "B": "At 45° to the b-axis", "C": "Perpendicular to the c-axis", "D": "Parallel to the vertical c-axis in the [100] zone (e.g. {100} orthopinacoid sections, where the b-axis = Y lies in the plane of the section)"}, "Dr. Ausaf Sayeed (Explanatory Note *39, p. 222); Nesse (p. 67); Bloss"),
    84: ("Triclinic Extinction: Universal Oblique Extinction", "In the Triclinic crystal system (e.g. Plagioclase feldspars, Kyanite), oblique (inclined) extinction is displayed by :", {"A": "Only basal sections", "B": "Only prismatic sections", "C": "Only macropinacoidal sections", "D": "All crystal sections in every possible orientation, because no optical indicatrix axis coincides with any crystallographic axis"}, "Nesse (Introduction to Optical Mineralogy, p. 68); Bloss (p. 132)"),
    85: ("Twinkling Optical Effect: Extreme Birefringence Anisotropy", "The 'twinkling' effect observed in Calcite and Muscovite upon rotating the microscope stage in plane-polarized light is caused by :", {"A": "A rapid, dramatic change in relief between high relief (n_omega = 1.658) and low relief (n_epsilon' ~ 1.53) as different vibration directions align with the lower polarizer", "B": "Internal total reflection from bubbles", "C": "Rapid flashing of pleochroic colors", "D": "Scattering from inclusions"}, "Nesse (Introduction to Optical Mineralogy, p. 29); Deer, Howie & Zussman"),
    86: ("Twinkling Minerals: Calcite and White Mica", "Which of the following minerals displays the most conspicuous and diagnostic 'twinkling' effect in standard thin sections ?", {"A": "Quartz (delta = 0.009, constant low relief)", "B": "Apatite (delta = 0.003)", "C": "Garnet (isotropic)", "D": "Calcite (delta = 0.172, extreme relief swing from 1.486 to 1.658)"}, "Nesse (Introduction to Optical Mineralogy, p. 29); Kerr"),
    87: ("The Universal Stage: Multi-Axis Petrographic Analysis", "The Fedorov Universal Stage (U-Stage) mounted on a petrographic microscope provides 4 or 5 independent axes of rotation, enabling the petrographer to :", {"A": "Measure the microhardness of grains", "B": "Determine the age of crystallization", "C": "Perform chemical microanalysis", "D": "Orient any optical indicatrix direction (X, Y, Z, or optic axis) precisely parallel to the microscope optical axis and accurately measure 2V, extinction angles, and twin laws"}, "E.S. Fedorov (1893); Emmons (The Universal Stage); Bloss"),
    88: ("Universal Stage: Optic Orientation Alignment", "On the Universal Stage, when a biaxial mineral is manipulated so that one of its optic axes is aligned vertically parallel to the microscope tube :", {"A": "The grain displays maximum interference colors", "B": "The grain flashes white", "C": "The grain remains completely extinct throughout a 360° rotation about the inner stage vertical axis", "D": "The grain exhibits pleochroism"}, "Emmons (The Universal Stage); Bloss (pp. 200–220)"),
    89: ("Monoclinic Optical Orientation: The ac Plane and b-Axis", "In monoclinic biaxial minerals, the symmetry plane (010) (the ac plane) contains :", {"A": "Two of the principal optical indicatrix directions (either X and Z, or X and Y, or Y and Z), while the crystallographic b-axis is strictly parallel to the third optical direction", "B": "All three optical directions", "C": "None of the optical directions", "D": "Only circular sections"}, "Dr. Ausaf Sayeed (Explanatory Note *39, p. 222); Nesse (p. 66); Bloss"),
    90: ("Maximum Double Refraction: Section Perpendicular to Y", "In any biaxial mineral, the maximum possible double refraction (delta_max = n_gamma - n_alpha) is displayed by a thin section cut :", {"A": "Parallel to the Optic Axial Plane (perpendicular to the Y optical direction, containing X and Z)", "B": "Perpendicular to the acute bisectrix", "C": "Perpendicular to the obtuse bisectrix", "D": "Parallel to one of the circular sections"}, "Wahlstrom (Optical Crystallography, p. 108); Nesse (p. 59)"),
    91: ("Optical Symmetry Restrictions: Systems with Fixed Indicatrix Axes", "In which of the following crystal systems are the three axes of the optical indicatrix (X, Y, Z) rigorously constrained by symmetry to coincide with the three crystallographic axes (a, b, c) ?", {"A": "Monoclinic system", "B": "Orthorhombic system", "C": "Triclinic system", "D": "Trigonal system"}, "Nesse (Introduction to Optical Mineralogy, p. 65); Bloss (p. 128)"),
    92: ("Biaxial Behavior as Uniaxial: Very Small 2V in Biotite and Sanidine", "For practical routine petrographic identification, a biaxial mineral with an exceptionally small optic axial angle (2V < 5° to 10°, such as Biotite or Sanidine) can be treated as :", {"A": "Essentially Uniaxial (giving a pseudo-uniaxial interference figure where the isogyres barely separate into a cross)", "B": "Optically Isotropic", "C": "Amorphous", "D": "Triclinic"}, "Nesse (Introduction to Optical Mineralogy, p. 94); Deer, Howie & Zussman"),
    93: ("Biaxial Positive vs. Negative: The Acute Bisectrix Standard", "A biaxial mineral is defined as Optically Positive when :", {"A": "Z (slow ray) is the Acute Bisectrix (Bxa), meaning 2V_z < 90°", "B": "X (fast ray) is the Acute Bisectrix (Bxa)", "C": "Y is the Acute Bisectrix", "D": "n_alpha = n_gamma"}, "Dr. Ausaf Sayeed (Explanatory Note *93, p. 222); Nesse (p. 60); Bloss"),
    94: ("Biaxial Coalescence: Transformation as 2V Approaches Zero", "As the optic axial angle 2V of a biaxial mineral approaches 0° :", {"A": "The two circular sections become mutually perpendicular", "B": "The two optic axes coalesce into a single optic axis, and the two circular sections merge into a single circular section, converting the mineral to Uniaxial", "C": "The mineral becomes opaque", "D": "Birefringence becomes infinite"}, "Dr. Ausaf Sayeed (Explanatory Note *94, p. 222); Wahlstrom (p. 112); Nesse"),
    95: ("Mica Plate Sign Determination: Quadrant Color Shifts", "When a quarter-wave mica plate (147 nm) is inserted into a centered uniaxial optic axis figure, two black spots (melatopes) appear in :", {"A": "All four quadrants simultaneously", "B": "The center only", "C": "Zero quadrants", "D": "The quadrants of subtraction (quadrants 2 and 4 for a positive crystal; quadrants 1 and 3 for a negative crystal)"}, "Bloss (Optical Crystallography, p. 88); Nesse (p. 80)"),
    96: ("Optical Dispersion: r > v vs. v > r in Biaxial Figures", "In biaxial interference figures, when the optic axial angle for red light is greater than for violet light (r > v), the color fringing on the concave side of the isogyres at the 45° position is :", {"A": "White", "B": "Red (with blue/violet on the convex side)", "C": "Yellow", "D": "Black"}, "Bloss (Optical Crystallography, pp. 148–155); Nesse (pp. 96–99)"),
    97: ("Dispersive Power: Refractive Index Variation with Wavelength", "The property of a mineral whereby its refractive index varies as a function of the wavelength of incident light (n_F - n_C) is termed :", {"A": "Optical dispersion (dispersive power)", "B": "Pleochroism", "C": "Birefringence", "D": "Optical activity"}, "Jenkins & White (Fundamentals of Optics); Nesse"),
    98: ("Fraunhofer Reference Lines: Standard Wavelengths in Optical Mineralogy", "In standard refractometry and optical mineralogy, the F-Fraunhofer line corresponds to the hydrogen blue emission line at a wavelength of :", {"A": "5893 Angstroms (Sodium D line)", "B": "6563 Angstroms (Hydrogen C line)", "C": "4308 Angstroms (G line)", "D": "4861 Angstroms (Hydrogen F line)"}, "Bloss (Optical Crystallography, p. 12); Jenkins & White"),
    99: ("Optical Anomalies: Strain Birefringence in Garnet and Analcime", "The weak, anomalous birefringence and mottled extinction frequently observed in theoretically isotropic minerals (such as Grossular garnet or Leucite) is termed an 'optical anomaly' and is caused by :", {"A": "Complete transformation into quartz", "B": "Radioactive alpha-decay", "C": "Internal lattice strain, partial Al-Si or Fe-Al cation ordering, or submicroscopic twinning during cooling from high temperatures", "D": "Surface polishing scratches"}, "Deer, Howie & Zussman (Rock-Forming Minerals); Nesse (p. 36)"),
    100: ("Bird's Eye Extinction: Mottled Extinction in Micas", "The characteristic speckled, mottled, 'bird's eye' or 'pebbly' extinction displayed by Biotite and Muscovite near the extinction position is caused by :", {"A": "Slight mechanical buckling, crinkling, and distortion of the flexible {001} cleavage sheets during thin section grinding", "B": "Microscopic exsolution lamellae", "C": "Chemical alteration to chlorite", "D": "Optical dispersion"}, "Nesse (Introduction to Optical Mineralogy, p. 235); Deer, Howie & Zussman"),
    101: ("Plagioclase Twinning: Albite Law Optical Features", "In petrographic thin sections, plagioclase feldspars are universally recognized by polysynthetic (multiple) lamellar twinning on the :", {"A": "Carlsbad law (simple twin with single composition plane)", "B": "Baveno law", "C": "Manebach law", "D": "Albite law (twin plane and composition plane parallel to {010}, producing alternating light and dark extinction stripes under crossed polarizers)"}, "Deer, Howie & Zussman (Rock-Forming Minerals, pp. 380–395); Nesse"),
    102: ("Microcline Twinning: Tartan Gridiron Cross-Hatching", "The diagnostic optical feature that unequivocally distinguishes Microcline from Orthoclase and Plagioclase in thin sections is :", {"A": "Straight extinction", "B": "Cross-hatched 'tartan' or 'gridiron' twinning (mutually perpendicular spindle-shaped lamellae formed by combined Albite and Pericline laws)", "C": "Uniaxial negative character", "D": "High relief"}, "Deer, Howie & Zussman (Introduction to the Rock-Forming Minerals, pp. 405–410); Nesse"),
    103: ("Orthoclase Twinning: Simple Carlsbad Twins", "In granitic rocks, Orthoclase phenocrysts commonly display simple contact twins composed of two halves extinguishing at different angles across a single straight boundary, representing the :", {"A": "Albite law", "B": "Pericline law", "C": "Tartan law", "D": "Carlsbad twin law (twin axis [001], composition plane {010})"}, "Deer, Howie & Zussman (Rock-Forming Minerals); Nesse"),
    104: ("Quartz vs. Orthoclase: Petrographic Differentiation", "Under the petrographic microscope, Quartz can be definitively distinguished from Orthoclase feldspar by its :", {"A": "High birefringence and cleavage", "B": "Strong pleochroism", "C": "Twin lamellae", "D": "Uniaxial positive optical character (Orthoclase is biaxial negative), completely water-clear freshness (free of sericitic alteration), and total absence of cleavage"}, "Nesse (Introduction to Optical Mineralogy, pp. 53, 240); Deer, Howie & Zussman"),
    105: ("Nepheline vs. Quartz: Optical Sign Distinction", "Both Nepheline and Quartz are uniaxial and possess very similar low refractive indices and low birefringence, but Nepheline is definitively identified by its :", {"A": "Uniaxial positive sign", "B": "Biaxial positive sign", "C": "Uniaxial negative optical sign (Quartz is uniaxial positive) and tendency to alter to cancrinite/zeolites", "D": "High double refraction"}, "Deer, Howie & Zussman (Rock-Forming Minerals, pp. 490–498); Nesse"),
    106: ("Apatite Optical Diagnostics: Uniaxial Negative Hexagonal Prisms", "Apatite Ca5(PO4)3(F,Cl,OH) is an omnipresent accessory mineral in igneous rocks, recognized in thin section by its :", {"A": "Hexagonal basal cross-sections (isotropic), elongated prismatic crystals with parallel extinction, length-fast character, moderate relief, and Uniaxial negative sign", "B": "Uniaxial positive character", "C": "Biaxial character with large 2V", "D": "Extreme birefringence"}, "Deer, Howie & Zussman (Rock-Forming Minerals, pp. 424–428); Nesse"),
    107: ("Tourmaline Optical Diagnostics: Uniaxial Negative with Maximum Absorption Perpendicular to Length", "Tourmaline is distinguished from Hornblende and Biotite in thin section by its :", {"A": "Biaxial positive character", "B": "Inclined extinction at 30°", "C": "Uniaxial negative character, lack of cleavage, and unique pleochroism where absorption is maximum when the length of the crystal is perpendicular to the polarizer vibration direction (length-fast)", "D": "Low relief"}, "Nesse (Introduction to Optical Mineralogy, p. 180); Deer, Howie & Zussman"),
    108: ("Epidote Optical Diagnostics: Pistachio Color and Third-Order Birefringence", "Epidote Ca2(Al,Fe)3Si3O12(OH) is easily recognized in metamorphic thin sections by its :", {"A": "Diagnostic yellowish-green ('pistachio') pleochroism, high relief (n ~ 1.74), bright second- to third-order interference colors, and biaxial negative character with large 2V", "B": "Complete optical isotropy", "C": "Uniaxial positive sign", "D": "Low negative relief"}, "Deer, Howie & Zussman (Rock-Forming Minerals, pp. 78–88); Nesse"),
    109: ("Andalusite Optical Diagnostics: Chiastolite Cross and Length-Fast", "Andalusite (Al2SiO5) is recognized in metapelites by its :", {"A": "Orthorhombic prismatic habit, moderate relief, low birefringence, length-fast character, Biaxial negative character with large 2V (73°-86°), and cruciform carbonaceous inclusion cross (var. Chiastolite)", "B": "Triclinic symmetry and inclined extinction", "C": "High positive birefringence", "D": "Optically isotropic character"}, "Deer, Howie & Zussman (Rock-Forming Minerals, pp. 68–72); Nesse"),
    110: ("Kyanite Optical Diagnostics: Bladed Metamorphic Habitus", "Kyanite (Al2SiO5) is identified in high-pressure pelitic schists by its :", {"A": "Isotropic character", "B": "Hexagonal prisms with zero birefringence", "C": "Bladed crystals with high relief (n ~ 1.72), two distinct cleavages ({100} and {010}), inclined extinction (Z ^ c = 30° on {100}), and Biaxial negative sign", "D": "Length-slow parallel extinction"}, "Deer, Howie & Zussman (Rock-Forming Minerals, pp. 72–77); Nesse"),
    111: ("Sillimanite Optical Diagnostics: Fibrolite Acicular Needles", "Sillimanite (Al2SiO5) is recognized in high-grade metamorphic rocks by its :", {"A": "Cubic cleavage and low relief", "B": "Slender prismatic or finely fibrous (fibrolite) needles, high relief, straight (parallel) extinction, length-slow character (positive elongation), and Biaxial positive sign with small 2V (20°-30°)", "C": "Inclined extinction at 45°", "D": "Uniaxial negative sign"}, "Deer, Howie & Zussman (Rock-Forming Minerals, pp. 75–78); Nesse"),
    112: ("Staurolite Optical Diagnostics: Golden Yellow Pleochroism and Sieve Texture", "Staurolite is unmistakably identified in medium-grade metapelites by its :", {"A": "Green pleochroism and low relief", "B": "Uniaxial positive character", "C": "Intense golden-yellow to honey-brown pleochroism, high relief (n ~ 1.74), Biaxial positive sign with large 2V (~85°), and characteristic 'swiss cheese' sieve (poikiloblastic) texture packed with quartz inclusions", "D": "Complete absence of inclusions"}, "Deer, Howie & Zussman (Rock-Forming Minerals, pp. 80–86); Nesse"),
    113: ("Garnet Optical Diagnostics: Complete Isotropy with High Relief", "In standard rock thin sections, Garnet group minerals are diagnosed immediately by their :", {"A": "Bright second-order interference colors", "B": "Multiple cleavage planes at 90°", "C": "Strong pleochroism", "D": "Complete optical isotropy (remains completely extinct under crossed polarizers), very high positive relief, rounded porphyroblastic habit, and prominent irregular fractures devoid of true cleavage"}, "Deer, Howie & Zussman (Rock-Forming Minerals, pp. 20–35); Nesse"),
    114: ("Cordierite Optical Diagnostics: Sector Twinning and Pinitization", "Cordierite (Mg,Fe)2Al4Si5O18 is often confused with Quartz in thin sections, but is distinguished by :", {"A": "Its Biaxial character, cyclic/sector pseudo-hexagonal twinning, yellow pleochroic halos around radioactive zircon inclusions, and distinctive alteration along margins to yellowish-green 'pinite' (fine mica/chlorite)", "B": "Uniaxial positive character", "C": "High birefringence", "D": "Total absence of alteration"}, "Deer, Howie & Zussman (Rock-Forming Minerals, pp. 90–98); Nesse"),
    115: ("Olivine Optical Diagnostics: High Birefringence and Serpentinous Alteration", "Olivine (Mg,Fe)2SiO4 in basaltic and peridotitic thin sections is identified by :", {"A": "High relief, vivid second- and third-order interference colors, Biaxial character with large 2V (~90°), total absence of cleavage, and irregular curved fractures filled with green serpentine and secondary magnetite", "B": "Perfect prismatic cleavage at 87°", "C": "Low birefringence identical to quartz", "D": "Optically isotropic character"}, "Deer, Howie & Zussman (Rock-Forming Minerals, pp. 3–15); Nesse"),
    116: ("Pyroxene vs. Amphibole: Definitive Optical Criteria", "The two most crucial optical criteria for discriminating Pyroxenes from Amphiboles in petrographic thin sections are :", {"A": "Cleavage intersection angle in basal cross-sections (~87°/93° in pyroxenes vs. ~56°/124° in amphiboles) and maximum extinction angle in prismatic sections (Z ^ c = 36°-48° in clinopyroxenes vs. 15°-25° in hornblende)", "B": "Color and streak", "C": "Specific gravity only", "D": "Pleochroism only"}, "Deer, Howie & Zussman (Rock-Forming Minerals); Nesse (pp. 140–165)"),
    117: ("Titanite (Sphene) Optical Diagnostics: Extreme Birefringence and High Relief", "Titanite (Sphene) CaTiSiO5 is easily identified in intermediate and calc-alkaline igneous rocks by its :", {"A": "Low relief and lack of color", "B": "Isotropic character", "C": "Uniaxial negative character", "D": "Characteristic acute rhombic or envelope-like cross-sections, extremely high relief (n ~ 1.90–2.03), and extreme birefringence (delta = 0.160–0.190) producing washed-out high-order pastel colors with total lack of extinction in white light due to intense dispersion"}, "Deer, Howie & Zussman (Rock-Forming Minerals, pp. 60–66); Nesse"),
    118: ("Zircon Optical Diagnostics: High Relief Tetragonal Inclusions", "Zircon (ZrSiO4) in granitic and metamorphic thin sections is recognized by :", {"A": "Negative relief and low birefringence", "B": "Isotropic character", "C": "Minute, highly polished euhedral tetragonal prismatic crystals, extremely high relief (n ~ 1.92–1.98), very high birefringence (delta ~ 0.06), Uniaxial positive character, and pleochroic halos in enclosing biotite", "D": "Basal cleavage"}, "Deer, Howie & Zussman (Rock-Forming Minerals, pp. 45–52); Nesse"),
    119: ("Scapolite Optical Diagnostics: Uniaxial Negative Tetragonal Mineral", "Scapolite (Marialite-Meionite series) is distinguished from Plagioclase and Quartz in calc-silicate rocks by its :", {"A": "Biaxial positive sign", "B": "Uniaxial negative optical sign (Tetragonal system), straight extinction along prismatic cleavages, and moderate to high birefringence (delta = 0.010 to 0.038)", "C": "Polysynthetic albite twinning", "D": "Isotropic character"}, "Dr. Ausaf Sayeed (Explanatory Note *119, p. 222); Deer, Howie & Zussman (pp. 480–488); Nesse"),
    120: ("Carbonate Staining: Alizarin Red S for Calcite vs. Dolomite", "In carbonate petrography, Calcite is readily distinguished from Dolomite in unstained and stained thin sections because :", {"A": "Calcite is isotropic while dolomite is anisotropic", "B": "Dolomite has low relief", "C": "Calcite displays straight extinction while dolomite displays inclined extinction", "D": "Calcite stains rapidly dark pink/red in dilute acid solution of Alizarin Red S within 1–2 minutes, whereas Dolomite remains completely unstained under the same conditions"}, "Dickson (1966, A modified staining technique for carbonates in thin section); Sam Boggs Jr.; Nesse"),
    121: ("Gypsum Optical Diagnostics: Low Birefringence Monoclinic Sulfate", "Gypsum (CaSO4.2H2O) in evaporite thin sections is recognized by its :", {"A": "High positive relief and extreme birefringence", "B": "Isotropic character", "C": "Uniaxial negative character", "D": "Low relief (n ~ 1.52), low birefringence (delta = 0.010, first-order gray-white colors), three cleavage directions (one perfect on {010}), inclined extinction, and Biaxial positive sign with large 2V (58°)"}, "Deer, Howie & Zussman (Rock-Forming Minerals, pp. 450–456); Nesse"),
    122: ("Barite Optical Diagnostics: High Density Biaxial Sulfate", "Barite (BaSO4) is identified in hydrothermal veins and sedimentary rocks by its :", {"A": "Moderate positive relief (n ~ 1.64), low birefringence (delta = 0.012), straight extinction parallel to cleavages, and Biaxial positive character with moderate 2V (37°)", "B": "Isotropic character", "C": "Uniaxial positive sign", "D": "High pleochroism"}, "Deer, Howie & Zussman (Rock-Forming Minerals, pp. 460–465); Nesse"),
    123: ("Fluorite Optical Diagnostics: Isotropic with Negative Relief", "Fluorite (CaF2) is distinguished under the polarizing microscope by its :", {"A": "Complete optical isotropy, distinctive negative relief (n = 1.434 < n_balsam = 1.537), and perfect octahedral cleavage in four directions {111}", "B": "High positive relief and birefringence", "C": "Biaxial positive sign", "D": "Length-slow elongation"}, "Nesse (Introduction to Optical Mineralogy, p. 110); Kerr"),
    124: ("Halite Optical Diagnostics: Isotropic Halide Matching Balsam", "Halite (NaCl) in evaporite sections is characterized by :", {"A": "High birefringence", "B": "Complete optical isotropy, refractive index (n = 1.544) virtually matching quartz and near Canada balsam, very low relief, and perfect 3-directional cubic cleavage {001}", "C": "Strong pleochroism", "D": "Uniaxial negative character"}, "Nesse (Introduction to Optical Mineralogy, p. 112); Kerr"),
    125: ("Petrographic Synthesis: Systematic Mineral Identification Workflow", "In professional optical mineralogy, the comprehensive logical sequence for identifying an unknown mineral in thin section follows the hierarchy :\n(1) Plane-polarized light: Color, pleochroism, habit, cleavage, relief (Becke line)\n(2) Crossed polarizers: Isotropy vs. anisotropy, birefringence order, extinction angle, twinning\n(3) Conoscopic illumination: Interference figure (Uniaxial vs. Biaxial), optic sign (+ or -), and 2V\nThis rigorous systematic workflow is established by :", {"A": "Casual visual estimation only", "B": "Chemical dissolution only", "C": "Standard classical optical mineralogy methodology documented in authoritative treatises by Bloss, Nesse, Wahlstrom, and Deer, Howie & Zussman", "D": "Bulk density measurement"}, "Bloss (Optical Crystallography); Nesse (Introduction to Optical Mineralogy); Wahlstrom")
}

